[CmdletBinding()]
param([string]$RepositoryRoot,[string]$ReaderDirectory,[string]$EvidenceSource,[string]$FixtureSource,[string]$CumulativeSource,[string]$RequestSeed,[Alias('OutputRoot')][string]$OutputDirectory)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(-not$RepositoryRoot){$RepositoryRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))}
if(-not$ReaderDirectory){$ReaderDirectory=Join-Path $RepositoryRoot 'scripts/runtime'}
if(-not$EvidenceSource){$EvidenceSource=Join-Path $ReaderDirectory 'Chunk7AssistedAcquisitionEvidence.ps1'}
if(-not$FixtureSource){$FixtureSource=Join-Path $ReaderDirectory 'Chunk7AssistedAcquisitionFixtures.ps1'}
if(-not$CumulativeSource){$CumulativeSource=Join-Path $ReaderDirectory 'Chunk7CumulativeAcquisitionEvidence.ps1'}
if(-not$RequestSeed){$RequestSeed=Join-Path $RepositoryRoot 'tests/Chunk7Diagnostics/AssistedAcquisitionConnectionFixture.json'}
if(-not$OutputDirectory){$OutputDirectory=Join-Path ([IO.Path]::GetDirectoryName([IO.Path]::GetDirectoryName($RepositoryRoot))) ('analysis-cache/chunk7-continuation/assisted-source-'+[Guid]::NewGuid().ToString('N'))}
$OutputRoot=$OutputDirectory
. (Join-Path $RepositoryRoot 'scripts/runtime/RuntimeHarness.Common.ps1')
. (Join-Path $RepositoryRoot 'scripts/runtime/Chunk7AssistedFixtureFixtures.ps1')
$actualLab=Get-KmcLabRoot;$out=Assert-KmcChildPath $OutputRoot (Join-Path $actualLab 'analysis-cache') 'generated connection source checks';if(Test-Path -LiteralPath $out){throw 'Keep previous checks.'};[void][IO.Directory]::CreateDirectory($out)
$inputs=@($EvidenceSource,$FixtureSource,$CumulativeSource,$RequestSeed,$PSCommandPath)|ForEach-Object{[pscustomobject]@{path=$_;sha256=(Get-KmcSha256 $_)}}
foreach($runtime in @(Get-ChildItem -LiteralPath (Join-Path $RepositoryRoot 'scripts/runtime') -Filter '*.ps1' -File)){$inputs+=,[pscustomobject]@{path=$runtime.FullName;sha256=(Get-KmcSha256 $runtime.FullName)}}
. $EvidenceSource;. $CumulativeSource;. $FixtureSource
function Clone($value){return (ConvertFrom-Json -InputObject (ConvertTo-Json -InputObject $value -Depth 90 -Compress))}
function Put([string]$Path,$Value){[void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($Path));[IO.File]::WriteAllText($Path,(ConvertTo-Json -InputObject $Value -Depth 90),[Text.UTF8Encoding]::new($false))}
function Pin([string]$Path){$i=Get-Item -LiteralPath $Path;[pscustomobject]@{path=$Path;sha256=(Get-KmcSha256 $Path);length=$i.Length;lastWriteTimeUtcTicks=$i.LastWriteTimeUtc.Ticks}}
function Need([bool]$Value,[string]$Message){if(-not$Value){throw $Message}}
# External completed-producer and full native-artifact/projection boundaries are
# separately covered. This adapter executes the actual new cold receipt/owner,
# restoration, immutable-file and locked dual-copy predicates with generated files.
function Get-KmcLabRoot {$script:lab}
function Get-KmcChunk7AssistedFixtureSource($Selection,$Fixture,$Candidate){$script:producerCalls++;if($script:rejectProducer){throw 'Generated producer gate refusal.'};Assert-KmcAssistedSame $Selection $script:producerPins 'exact source delegation';Assert-KmcAssistedSame $Candidate $script:candidate 'exact candidate delegation';Assert-KmcAssistedSame $Fixture $script:fixture 'exact fixture delegation';$script:producer}
function Assert-KmcReadOnlyArtifactManifest($Request,$Hash,[switch]$GameResult){$script:manifestCalls++;Need ($Hash-ceq(Get-KmcSha256 (Join-Path $script:evidenceRoot 'runtime-artifacts.json'))) 'Manifest delegation differs.'}
function Assert-KmcChunk7AssistedColdInventoryArtifact($Request,$Manifest,$Status){$script:artifactCalls++;Need ($Status-ceq'PASS') 'Artifact status differs.'}
function Assert-KmcChunk7AssistedColdInventoryEvidence($Request,$Cold,$Producer,$Status){$script:evidenceCalls++;Need ($Status-ceq'PASS') 'Evidence status differs.'}
function Assert-KmcAssistedCumulativeSource($Request,$Producer,$Cold){$script:projectionCalls++;Assert-KmcChunk7CumulativeDescriptor $Request;[pscustomobject]@{externalProjection=$true}}
$seed=Get-Content -LiteralPath $RequestSeed -Raw|ConvertFrom-Json
if($null-ne$seed.PSObject.Properties['request']){$seed=$seed.request}
$script:number=0;$script:passed=0;$script:failed=0;$rows=[Collections.Generic.List[object]]::new();$timer=[Diagnostics.Stopwatch]::StartNew()
function New-Fixture {
 $script:number++;$script:lab=Join-Path $out ('c'+$script:number);$r=Clone $seed;$s=$r.cumulativeAcquisition;$s.sourceRunId='producer-'+$script:number;$s.assistedColdRunId='cold-'+$script:number
 $script:fixture=$r.fixture;$script:candidate=[pscustomobject]@{commit=$r.commit;dllSha256=$r.dllSha256;dllMvid=$r.dllMvid}
 $sourceRoot=Join-Path $script:lab ('runtime-evidence/'+$s.sourceRunId);$sourceProfile=Join-Path $script:lab ('runtime-staging/persistence-'+$s.sourceRunId)
 $archive=Join-Path $sourceProfile ('Saved Games/'+$r.persistenceLoad.fileName);Put $archive ([pscustomobject]@{generated='no archive format';case=$script:number});$d=Clone $r.persistenceLoad;$f=Get-Item -LiteralPath $archive;$d.sha256=Get-KmcSha256 $archive;$d.length=$f.Length;$d.lastWriteTimeUtcTicks=$f.LastWriteTimeUtc.Ticks;$s.sourceArchiveSha256=$d.sha256
 $sourcePins=@();foreach($leaf in @('runtime-request.json','runtime-result.json','runtime-game-result.json','runtime-artifacts.json','base-game-isolation-result.json','profile-cache-changes.json','chunk7-assisted-fixture-evidence.json')){$p=Join-Path $sourceRoot $leaf;Put $p ([pscustomobject]@{generated=$leaf});$sourcePins+=,(Pin $p)};$sourceOwner=Join-Path $sourceProfile 'owner.json';Put $sourceOwner ([pscustomobject]@{generated='owner'});$sourcePins+=,(Pin $sourceOwner)
 $sourceArtifact=Join-Path $sourceRoot 'chunk7-assisted-fixture-evidence.json';$s.sourceArtifactSha256=Get-KmcSha256 $sourceArtifact
 $script:producerPins=[pscustomobject]@{sourceRunId=$s.sourceRunId;sourceArtifactSha256=$s.sourceArtifactSha256;sourceArchiveSha256=$s.sourceArchiveSha256}
 $script:producer=[pscustomobject]@{path=$archive;descriptor=$d;artifactPath=$sourceArtifact;artifactSha256=$s.sourceArtifactSha256;artifactLength=(Get-Item -LiteralPath $sourceArtifact).Length;sourceRunId=$s.sourceRunId;receiptPins=$sourcePins}
 $script:evidenceRoot=Join-Path $script:lab ('runtime-evidence/'+$s.assistedColdRunId);$profile=Join-Path $script:lab ('runtime-staging/persistence-'+$s.assistedColdRunId);[void][IO.Directory]::CreateDirectory((Join-Path $profile 'Saved Games'))
 $coldSelection=[pscustomobject]@{case='assisted-manual-readonly-inventory';sourceRunId=$s.sourceRunId;sourceArtifactSha256=$s.sourceArtifactSha256;sourceArchiveSha256=$s.sourceArchiveSha256;baseGameOnly=$true;expectedNativeLoadCount=1;expectedNativeWriteCount=0}
 $request=[pscustomobject]@{schemaVersion=2;runId=$s.assistedColdRunId;scenario='chunk7-assisted-cold-inventory';evidenceRoot=$script:evidenceRoot;branch=$r.branch;commit=$r.commit;productVersion=$r.productVersion;dllSha256=$r.dllSha256;dllMvid=$r.dllMvid;transactionToken=('a'*64);fixture=$r.fixture;assistedColdInventory=$coldSelection;persistenceLoad=$d}
 $owner=[pscustomobject]@{runId=$request.runId;scenario=$request.scenario;transactionToken=$request.transactionToken;persistenceCase=$null;sourceSha256=$d.sha256;saveRoot=(Join-Path $profile 'Saved Games')};Put (Join-Path $profile 'owner.json') $owner
 $manifest=[pscustomobject]@{generated='manifest'};Put (Join-Path $script:evidenceRoot 'runtime-artifacts.json') $manifest
 $game=[pscustomobject]@{schemaVersion=2;runId=$request.runId;scenario=$request.scenario;branch=$request.branch;commit=$request.commit;productVersion=$request.productVersion;dllSha256=$request.dllSha256;dllMvid=$request.dllMvid;transactionToken=$request.transactionToken;status='PASS';errors=@();assertionFailCount=0;subscenarioFailCount=0;evidenceManifestSha256=(Get-KmcSha256 (Join-Path $script:evidenceRoot 'runtime-artifacts.json'));loadRequestCount=1;workingLoadRequestCount=1;baselineLoadRequestCount=0;unauthorizedLoadRequestCount=0;unauthorizedSaveRequestCount=0;saveRequestCount=0;workingSaveRequestCount=0;fixtureIdentityVerified=$true;movementExperimentEnabled=$false;currentGameMode='Default';loadedAreaPresent=$true}
 $result=Clone $game;foreach($name in @('modsRestored','workingRestored','baselineImmutable','saveProtectionPassed','saveWriteAllowlistPassed')){$result|Add-Member NoteProperty $name $true};$result|Add-Member NoteProperty restoredSaveInventoryDigest ('d'*64);$result|Add-Member NoteProperty gameResultSha256 ''
 $isolation=[pscustomobject]@{runId=$request.runId;stagingMode='base-game-only-kmc';stageVerified=$true;dependenciesUnchanged=$true;processExited=$true;modsRestored=$true;saveProtectionPassed=$true;gameReportedPass=$true;nativeInventoryObserved=$true;nativeCompatibilityQualified=$true}
 $cache=[pscustomobject]@{schemaVersion=1;runId=$request.runId;profileRoot='generated external-profile label only';policy='native-achievement-cache-settled-size';snapshotProfileDigest=('e'*64);profileBytesRestoredExactly=$true;acceptedNativeCacheChanges=@()}
 $cold=[pscustomobject]@{generated='cold artifact'};Put (Join-Path $script:evidenceRoot 'chunk7-assisted-cold-inventory-evidence.json') $cold;$s.assistedColdArtifactSha256=Get-KmcSha256 (Join-Path $script:evidenceRoot 'chunk7-assisted-cold-inventory-evidence.json')
 $script:producerCalls=0;$script:rejectProducer=$false;$script:manifestCalls=0;$script:artifactCalls=0;$script:evidenceCalls=0;$script:projectionCalls=0
 [pscustomobject]@{selection=$s;request=$request;result=$result;game=$game;isolation=$isolation;cache=$cache;owner=$owner;profile=$profile;root=$script:evidenceRoot;fixture=$r.fixture;candidate=$script:candidate;omitCache=$false;rejectProducer=$false}
}
function Save-Fixture($f){Put (Join-Path $f.root 'runtime-request.json') $f.request;Put (Join-Path $f.root 'runtime-game-result.json') $f.game;$f.result.gameResultSha256=Get-KmcSha256 (Join-Path $f.root 'runtime-game-result.json');Put (Join-Path $f.root 'runtime-result.json') $f.result;Put (Join-Path $f.root 'base-game-isolation-result.json') $f.isolation;Put (Join-Path $f.profile 'owner.json') $f.owner;if(-not$f.omitCache){Put (Join-Path $f.root 'profile-cache-changes.json') $f.cache}}
function Check([string]$Name,[bool]$Expected,[scriptblock]$Mutate,[switch]$Copy){$accepted=$true;$errorText=$null;$ready=$false;$lock=$null;$closed=$true
 try{$f=New-Fixture;&$Mutate $f;$script:rejectProducer=$f.rejectProducer;Save-Fixture $f;$ready=$true;$qualified=Get-KmcAssistedCumulativeSource $f.selection $f.fixture $f.candidate
 if($Copy){$run='consumer-'+$script:number;$lock=Open-KmcRuntimeLock (Join-Path $script:lab 'runtime-state') $run;$profile=Join-Path $script:lab ('runtime-staging/persistence-'+$run);[void][IO.Directory]::CreateDirectory((Join-Path $profile 'Saved Games'));Put (Join-Path $profile 'owner.json') ([pscustomobject]@{runId=$run;scenario='chunk7-cumulative-acquisition';transactionToken=$lock.Token;persistenceCase=$null;sourceSha256=$qualified.descriptor.sha256;saveRoot=(Join-Path $profile 'Saved Games')});Copy-KmcAssistedCumulativeSourceArtifacts $qualified $profile $lock $f.selection $f.fixture $f.candidate;Need ((Get-KmcSha256 (Join-Path $profile 'cumulative-acquisition-source.json'))-ceq$f.selection.sourceArtifactSha256) 'Producer copy differs';Need ((Get-KmcSha256 (Join-Path $profile 'cumulative-assisted-cold-source.json'))-ceq$f.selection.assistedColdArtifactSha256) 'Cold copy differs'}
 Need ($script:producerCalls-ge1-and$script:manifestCalls-ge1-and$script:artifactCalls-ge1-and$script:evidenceCalls-ge1-and$script:projectionCalls-ge1) 'A required qualification boundary was skipped'
 }catch{$accepted=$false;$errorText=$_.Exception.Message}finally{if($null-ne$lock){try{Close-KmcRuntimeLock $lock}catch{$closed=$false;$errorText=$_.Exception.Message}}}
 $ok=$ready-and$closed-and$accepted-eq$Expected;if($ok){$script:passed++}else{$script:failed++};$rows.Add([pscustomobject]@{name=$Name;expectedAccepted=$Expected;actualAccepted=$accepted;fixtureReady=$ready;lockClosed=$closed;status=$(if($ok){'PASS'}else{'FAIL'});error=$errorText});Write-Output ($(if($ok){'PASS '}else{'FAIL '})+$Name+$(if(-not$ok){': '+$errorText}else{''}))
}
Check 'complete producer and cold restoration admit unchanged Manual' $true {param($f)}
Check 'actual locked dual source copy retains producer and cold bytes' $true {param($f)} -Copy
Check 'cold source records admitted native cache change distinctly' $true {param($f)$f.cache.profileBytesRestoredExactly=$false;$f.cache.acceptedNativeCacheChanges=@([pscustomobject]@{path='achievements.dat';change='created';length=12288;beforeSha256='';afterSha256=('a'*64)})}
Check 'missing cold profile restoration refuses' $false {param($f)$f.omitCache=$true}
foreach($name in @('foreign-run','schema','policy','digest','not-exact','accepted-changes','changes-scalar','exact-array')){Check ('cold profile restoration '+$name+' refuses') $false {param($f)switch($name){'foreign-run'{$f.cache.runId='other'}'schema'{$f.cache.schemaVersion=2}'policy'{$f.cache.policy='other'}'digest'{$f.cache.snapshotProfileDigest='bad'}'not-exact'{$f.cache.profileBytesRestoredExactly=$false}'accepted-changes'{$f.cache.acceptedNativeCacheChanges=@([pscustomobject]@{path='changed'})}'changes-scalar'{$f.cache.acceptedNativeCacheChanges=''}'exact-array'{$f.cache.profileBytesRestoredExactly=@($true)}}}.GetNewClosure()}
foreach($name in @('result-schema','game-schema','result-assertions','result-subscenarios','game-save','game-load','game-mode','owner-source','producer-gate','foreign-candidate','cold-selection-source','restoration-flag')){Check ('completed cold '+$name+' refuses') $false {param($f)switch($name){'result-schema'{$f.result.schemaVersion=1}'game-schema'{$f.game.schemaVersion=1}'result-assertions'{$f.result.assertionFailCount=1}'result-subscenarios'{$f.result.subscenarioFailCount=1}'game-save'{$f.game.saveRequestCount=1}'game-load'{$f.game.loadRequestCount=0}'game-mode'{$f.game.currentGameMode='Dialog'}'owner-source'{$f.owner.sourceSha256='f'*64}'producer-gate'{$f.rejectProducer=$true}'foreign-candidate'{$f.request.dllSha256='f'*64}'cold-selection-source'{$f.request.assistedColdInventory.sourceRunId='other'}'restoration-flag'{$f.result.workingRestored=$false}}}.GetNewClosure()}
$timer.Stop();foreach($pin in $inputs){if((Get-KmcSha256 $pin.path)-cne$pin.sha256){throw 'Focused input changed.'}}
[pscustomobject]@{status=$(if($script:failed){'FAIL'}else{'PASS'});passed=$script:passed;failed=$script:failed;durationSeconds=$timer.Elapsed.TotalSeconds;cases=$rows.ToArray();inputs=$inputs;substitutions=@('Complete producer qualification, full cold artifact/evidence and source projection are explicit separately tested external boundaries.','New qualifier/copy, real generated receipt/owner/path/link/hash/lock checks execute. No archive content parsed.');nativeInvoked=$false;actualArchivesRead=$false}|ConvertTo-Json -Depth 30|Set-Content -LiteralPath (Join-Path $out 'receipt.json') -Encoding UTF8
if($script:failed){exit 1}
